"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["21541"],{66595(e){e.exports=JSON.parse('{"id":"F511","slug":"afn-external-financing","name":"Additional Funds Needed (Percent-of-Sales Forecast)","subject":"Accounting Mastery & Financial Modeling","section":"Modeling craft","topic":"Modeling craft","level":"Intermediate","aliases":["external financing needed","AFN","percent of sales method","forecasting balance sheet"],"formula":{"latex":"AFN=\\\\frac{A}{S}\\\\Delta S-\\\\frac{L}{S}\\\\Delta S-PM\\\\times S_{1}\\\\times(1-d)","also":[],"text":"Additional funds needed = (Assets/Sales) x Change in sales - (Spontaneous liabilities/Sales) x Change in sales - Net margin x New sales x (1 - Payout ratio)"},"symbols":[{"symbol":"A/S","meaning":"Assets that grow in step with sales, as a share of sales","unit":"percent"},{"symbol":"L/S","meaning":"Liabilities that grow in step with sales, such as payables and accruals","unit":"percent"},{"symbol":"Delta S","meaning":"Increase in sales","unit":"money"},{"symbol":"PM","meaning":"Net profit margin","unit":"percent"},{"symbol":"d","meaning":"Dividend payout ratio","unit":"percent"},{"symbol":"S_1","meaning":"Sales next year","unit":"money"}],"when_to_use":"Use it to forecast how much outside money a growing company will need. Assets grow with sales and need funding. Part of it is funded by liabilities that grow automatically and by profit kept in the business. What remains must come from new debt or equity, and this is the plug in a model.","worked_example":{"problem":"Sales are 1,000 and expected to grow 20% to 1,200. Assets are 80% of sales and spontaneous liabilities are 15% of sales. The net margin is 6% and 40% of profit is paid out as dividends.","inputs":{"s0":1000,"g":20,"a":80,"l":15,"pm":6,"d":40},"steps":[{"label":"Sales next year = sales x (1 + g)","working":"1000 x (1+0.2)","value":"1,200.00"},{"label":"Change in sales","working":"1200-1000","value":"200.00"},{"label":"Extra assets needed = A/S x change in sales","working":"0.8 x 200","value":"160.00"},{"label":"Extra spontaneous liabilities = L/S x change in sales","working":"0.15 x 200","value":"30.00"},{"label":"Retained profit = PM x new sales x (1 - payout)","working":"0.06 x 1200 x (1-0.4)","value":"43.20"},{"label":"AFN = extra assets - extra liabilities - retained profit","working":"160-30-43.2","value":"86.80"}],"answer":"Sales rise by 200.00. Assets need an extra 160.00, spontaneous liabilities provide 30.00 and retained profit provides 43.20. The company must raise 86.80 of outside funding."},"calculator":{"available":true,"inputs":[{"id":"s0","label":"Sales this year","unit":"money","type":"number","default":1000,"hint":""},{"id":"g","label":"Sales growth","unit":"%","type":"number","default":20,"hint":""},{"id":"a","label":"Assets as a share of sales","unit":"%","type":"number","default":80,"hint":""},{"id":"l","label":"Spontaneous liabilities as a share of sales","unit":"%","type":"number","default":15,"hint":""},{"id":"pm","label":"Net profit margin","unit":"%","type":"number","default":6,"hint":""},{"id":"d","label":"Dividend payout ratio","unit":"%","type":"number","default":40,"hint":""}],"checks":[],"steps":[{"id":"s1","label":"Sales next year = sales x (1 + g)","expr":"s0*(1+g)","format":"money"},{"id":"ds","label":"Change in sales","expr":"s1-s0","format":"money"},{"id":"da","label":"Extra assets needed = A/S x change in sales","expr":"a*ds","format":"money"},{"id":"dl","label":"Extra spontaneous liabilities = L/S x change in sales","expr":"l*ds","format":"money"},{"id":"re","label":"Retained profit = PM x new sales x (1 - payout)","expr":"pm*s1*(1-d)","format":"money"},{"id":"afn","label":"AFN = extra assets - extra liabilities - retained profit","expr":"da-dl-re","format":"money"}],"results":["afn"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"s1":1200,"ds":200,"da":160,"dl":30,"re":43.2,"afn":86.8}},"finder":{"finds":"How much outside funding growth needs","needs":"Sales, growth, asset and liability ratios, margin, payout"},"related":[{"slug":"sustainable-growth-rate","name":"Sustainable Growth Rate"},{"slug":"change-in-nwc","name":"Investment in Net Working Capital (Projects)"},{"slug":"dividend-payout-ratio","name":"Dividend Payout Ratio"}],"related_ids":["F176","F158","F175"],"group":"Companies and valuation","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>A</mi><mi>F</mi><mi>N</mi><mo>=</mo><mfrac><mi>A</mi><mi>S</mi></mfrac><mi mathvariant=\\"normal\\">\u0394</mi><mi>S</mi><mo>\u2212</mo><mfrac><mi>L</mi><mi>S</mi></mfrac><mi mathvariant=\\"normal\\">\u0394</mi><mi>S</mi><mo>\u2212</mo><mi>P</mi><mi>M</mi><mo>\xd7</mo><msub><mi>S</mi><mn>1</mn></msub><mo>\xd7</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>d</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">AFN=\\\\frac{A}{S}\\\\Delta S-\\\\frac{L}{S}\\\\Delta S-PM\\\\times S_{1}\\\\times(1-d)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"accrued-interest-dirty-price","name":"Accrued Interest and Dirty Price"},"next":{"slug":"adjusted-leverage-off-balance","name":"Adjusted Leverage with Off-Balance-Sheet Items"},"lesson":null,"total":522}')}}]);